const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const startDate = '2022-07-19';
  const endDate = '2022-07-20'; // Filter for a single day
  const targetTempFahrenheit = 100;

  // Define UK geometry using FAO/GAUL boundaries
  const countries = ee.FeatureCollection('FAO/GAUL/2015/level0');
  const uk = countries.filter(ee.Filter.eq('ADM0_NAME', 'United Kingdom'));
  const geom = uk.geometry();

  // 2. Data Acquisition & Check
  // Use MODIS/051/MOD11A1 for daily Land Surface Temperature (Day LST)
  let collection = ee.ImageCollection('MODIS/051/MOD11A1')
    .filterDate(startDate, endDate)
    .filterBounds(geom);

  const initialSize = await collection.size().getInfo();
  if (initialSize === 0) {
    console.log("No MODIS MOD11A1 images found for UK on July 19, 2022.");
    console.log("C1");
    return;
  }
  console.log(`Initial images found: ${initialSize}`);

  // Get the single image for the day
  const image = collection.first();

  // 3. Processing (Cloud Masking and Temperature Conversion)
  // LST_Day_00_QC band contains quality information.
  // Bits 0-1: LST quality (00: good quality, 01: LST produced, other quality not good)
  // Bits 2-3: Day/night (00: day)
  // Bits 4-5: Cloud coverage (00: cloudy, 01: clear)

  // Function to apply quality mask and convert LST to Fahrenheit
  const applyScaleAndMask = (img) => {
    const lstDay = img.select('LST_Day_00_05');
    const qc = img.select('LST_Day_00_QC');

    // Get the LST quality (bits 0-1) and Cloud state (bits 4-5)
    // LST_QC == 0 (good quality)
    const lstQualityMask = qc.bitwiseAnd(ee.Image(3)).eq(0);
    // Cloud_State == 1 (clear sky)
    const cloudStateMask = qc.rightShift(4).bitwiseAnd(ee.Image(3)).eq(1);

    // Combine masks
    const combinedMask = lstQualityMask.and(cloudStateMask);

    // Apply scaling factor (0.02 K) and convert to Celsius, then Fahrenheit
    const lstCelsius = lstDay.multiply(0.02).subtract(273.15);
    const lstFahrenheit = lstCelsius.multiply(9 / 5).add(32);

    return lstFahrenheit.updateMask(combinedMask).rename('LST_Fahrenheit');
  };

  const processedImage = applyScaleAndMask(image);

  // Calculate valid pixels after masking
  const pixelCount = await processedImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geom,
    scale: 1000, // MODIS resolution is 1km
    maxPixels: 1e9
  }).get('LST_Fahrenheit').getInfo();

  if (pixelCount === 0 || pixelCount === null) {
    console.log("No valid pixels remain after cloud masking for July 19, 2022.");
    console.log("C2");
    return;
  }
  console.log(`Valid pixels after masking: ${pixelCount}`);

  // 4. Calculation
  const maxTemp = await processedImage.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: geom,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Fahrenheit').getInfo();

  // 5. Validation & Final Answer
  if (maxTemp === null || isNaN(maxTemp)) {
    console.log("Failed to calculate maximum temperature.");
    console.log("C3");
    return;
  }

  console.log(`Max LST over UK on 2022-07-19: ${maxTemp.toFixed(2)} °F`);

  if (maxTemp > targetTempFahrenheit) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
